INSERT INTO learner_points (id, user_id, total_points, current_badge)
VALUES ('f6eda915-6e84-59a0-ab30-2332ebb622e9', '825a3274-ae7b-53d1-afaf-9425c79c0c5c', 20, 'Newbie')
